public class FileVersion
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid FileId { get; set; }
    public int VersionNumber { get; set; }
    public string ContentHash { get; set; }
    public Guid CreatedBy { get; set; }
    public DateTime CreatedAt { get; } = DateTime.UtcNow;
}

public class SyncEngine
{
    public async Task<SyncResult> SyncAsync(Guid userId, Guid fileId, string localHash)
    {
        var latest = _versions.GetLatest(fileId);
        if (latest.ContentHash == localHash)
            return SyncResult.UpToDate;

        var changes = _versions.GetChangesSince(fileId, localHash);
        return new SyncResult { Changes = changes, LatestHash = latest.ContentHash };
    }
}

